package com.example.gnss_imu_logger.playback
import java.io.File
class SessionLogReader {
 fun read(item:SessionListItem):PlaybackSession { val l=mutableListOf<PlaybackLocation>();val a=mutableListOf<PlaybackAttitude>();val e=mutableListOf<PlaybackEvent>();var rejected=0;fun d(r:Map<String,String>,n:String)=r[n]?.takeIf{it.isNotBlank()}?.toDoubleOrNull();
 File(item.directory,"gnss.csv").takeIf{it.isFile}?.let{CsvRowReader(it).forEachRow{r->runCatching{PlaybackLocation(r.getValue("elapsed_realtime_ns").toLong(),r.getValue("session_elapsed_ns").toLong(),r.getValue("latitude_deg").toDouble(),r.getValue("longitude_deg").toDouble(),d(r,"altitude_m"),d(r,"speed_mps"),d(r,"bearing_deg"),d(r,"horizontal_accuracy_m"))}.onSuccess{if(it.latitudeDeg.isFinite()&&it.longitudeDeg.isFinite())l+=it else rejected++}.onFailure{rejected++}}};File(item.directory,"lean_angle.csv").takeIf{it.isFile}?.let{CsvRowReader(it).forEachRow{r->runCatching{PlaybackAttitude(r.getValue("elapsed_realtime_ns").toLong(),d(r,"roll_rad"),d(r,"reference_roll_rad"),r["estimate_valid"].toBoolean(),AttitudeSource.RECORDED_LEAN_ANGLE)}.onSuccess{a+=it}.onFailure{rejected++}}};File(item.directory,"events.csv").takeIf{it.isFile}?.let{CsvRowReader(it).forEachRow{r->runCatching{PlaybackEvent(r.getValue("elapsed_realtime_ns").toLong(),r.getValue("session_elapsed_ns").toLong(),r["event_type"].orEmpty(),r["message"].orEmpty())}.onSuccess{e+=it}.onFailure{rejected++}}};l.sortBy{it.elapsedRealtimeNs};a.sortBy{it.elapsedRealtimeNs};e.sortBy{it.elapsedRealtimeNs};val first=listOfNotNull(l.firstOrNull()?.elapsedRealtimeNs,a.firstOrNull()?.elapsedRealtimeNs,e.firstOrNull()?.elapsedRealtimeNs).minOrNull()?:error("再生できるデータがありません");val last=listOfNotNull(l.lastOrNull()?.elapsedRealtimeNs,a.lastOrNull()?.elapsedRealtimeNs,e.lastOrNull()?.elapsedRealtimeNs).maxOrNull()?:first;return PlaybackSession(item,first,last,l,a,e,PlaybackDiagnostics(l.size,a.size,e.size,rejected,0,0.0,0)) }
}
